heights = list(map(int, input().split()))

# 总操作次数为 n
print(n)

# 第一步：对整个前缀取模 2
print(f"2 {n} 2")

# 后续 n-1 步：依次对前缀长度 1 到 n-1 加 2
for i in range(1, n):
    print(f"1 {i} 2")
```

